package main

import (
	"errors"
	"fmt"
)

type notFound struct{ name string }

func (e *notFound) Error() string { return e.name + " not found" }

var errBase = errors.New("base")

func main() {
	e1 := fmt.Errorf("layer1: %w", errBase)
	e2 := fmt.Errorf("layer2: %w", e1)
	fmt.Println(e2)
	fmt.Println(errors.Is(e2, errBase), errors.Is(e1, errBase), errors.Is(errBase, e1))
	fmt.Println(errors.Unwrap(e2) == e1, errors.Unwrap(e1) == errBase)

	var nf *notFound
	e3 := fmt.Errorf("outer: %w", &notFound{"cfg"})
	fmt.Println(errors.As(e3, &nf), nf.name)
	fmt.Printf("%v|%s\n", e3, e3)
}

